g=[[0]*30 for _ in range(30)]
for i in range(5):
  r=1+7*i
  for j in range(5):
    c=1+7*j
    for y in range(r,min(r+5,30)):
      for x in range(c,min(c+5,30)):
        g[y][x]=4
    if i<4 and j<4:
      col=colors[i][j]
      for y in range(r+1,r+4):
        for x in range(c+1,c+4): g[y][x]=col
# horizontal bridges, between all consecutive tile slots within the interval joining like colors
for i in range(4):
  for a in range(4):
    for b in range(a+1,4):
      if colors[i][a]==colors[i][b]:
        y=3+7*i
        for j in range(a,b):
          for x in (3+7*j+3,3+7*j+4): g[y][x]=colors[i][a]
# vertical bridges
for j in range(4):
  for a in range(4):
    for b in range(a+1,4):
      if colors[a][j]==colors[b][j]:
        x=3+7*j
        for i in range(a,b):
          for y in (3+7*i+3,3+7*i+4): g[y][x]=colors[a][j]
print('\n'.join(' '.join(map(str,row)) for row in g))

